### 3. 결과 타입(Result Type) 패턴
```python
from typing import Union, Optional

class Result:
    def __init__(self, value=None, error=None):
        self.value = value
        self.error = error
        self.is_success = error is None

# 순수 함수 - 성공/실패만 표현
def validate_email(email: str) -> Result:
    if '@' not in email:
        return Result(error='이메일 형식 오류')
    return Result(value=email.lower())

def validate_age(age: int) -> Result:
    if age < 0 or age > 150:
        return Result(error='나이 범위 오류')
    return Result(value=age)

# 불순한 작업은 별도로
def register_user(email: str, age: int):
    email_result = validate_email(email)
    if not email_result.is_success:
        return email_result

    age_result = validate_age(age)
    if not age_result.is_success:
        return age_result

    # 여기서만 실제 I/O
    try:
        user = db.create_user(email_result.value, age_result.value)
        send_welcome_email(user.email)
        return Result(value=user)
    except Exception as e:
        return Result(error=str(e))
```

## ⚠️ 주의해야 할 경계선

### 1. 로깅은 어떻게?
```python
# ❌ 순수 함수에 로깅 섞기
def calculate_discount(price, discount_rate):
    print(f"할인 계산: {price} * {discount_rate}")  # 부작용
    return price * discount_rate

# ✅ 로깅과 계산 분리
def calculate_discount(price, discount_rate):
    return price * discount_rate

def apply_discount_with_logging(price, discount_rate):
    result = calculate_discount(price, discount_rate)
    print(f"할인 적용: {price} → {result}")
    return result
```

### 2. 캐싱은?
```python
# ❌ 함수 내부에 캐시
cache = {}
def expensive_calculation(n):
    if n in cache:
        return cache[n]
    result = complex_math(n)
    cache[n] = result  # 부작용
    return result

# ✅ 캐시를 외부에서 관리
def expensive_calculation(n):
    return complex_math(n)

# 캐싱은 호출하는 쪽에서
@lru_cache(maxsize=128)
def cached_expensive_calculation(n):
    return expensive_calculation(n)
```

### 3. 예외 처리는?
```python
# ✅ 예외 대신 명시적 반환
def divide_safe(a, b):
    if b == 0:
        return None  # 또는 Result 타입 사용
    return a / b

# 또는 Maybe/Optional 패턴
from typing import Optional

def divide_maybe(a: float, b: float) -> Optional[float]:
    return None if b == 0 else a / b
```

핵심은 **계산과 효과를 명확히 분리**하는 거야. 순수 함수는 정말 계산만 하게 하고, I/O나 상태 변경은 시스템의 가장자리에서만 처리하는 게 좋아. 이렇게 하면 테스트도 쉽고 버그도 줄어들거든.
